data.code:
extend schema @link(
  url: "https://specs.apollo.dev/federation/v2.3",
  import: ["@key", "@shareable"]
)

type User @key(fields: "id") {
  id: ID!
  name: String!
  email: String
}

type Query {
  me: User
  user(id: ID!): User
}

extend schema @link(
  url: "https://specs.apollo.dev/federation/v2.3",
  import: ["@key", "@external"]
)

type Review {
  id: ID!
  body: String!
  author: User!
}

type User @key(fields: "id") {
  id: ID! @external
  reviews: [Review!]!
}
